from itertools import product

def transforms(S):
    out=[]
    for k in range(4):
      for f in (False,True):
        pts=[]
        for r,c in S:
          if f:c=-c
          for _ in range(k): r,c=c,-r
          pts.append((r,c))
        mr=min(r for r,c in pts); mc=min(c for r,c in pts)
        norm=frozenset((r-mr,c-mc) for r,c in pts)
        if norm not in [x[1] for x in out]:out.append((f'rot{k*90}'+('_flip' if f else ''),norm))
    return out

def cand(template,seeds):
  res=[]
  sr0=min(r for r,c in seeds); sr1=max(r for r,c in seeds); sc0=min(c for r,c in seeds); sc1=max(c for r,c in seeds)
