def transform(grid):
    """Overlay translated copies of the largest non-background motif."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row if v != 1}
    if not colors:
        return out
    parts = {color: {(r, c) for r in range(h) for c in range(w)
                     if grid[r][c] == color} for color in colors}
    exemplar_color = max(colors, key=lambda color: len(parts[color]))
    exemplar = parts[exemplar_color]
    r0, c0 = min(r for r, c in exemplar), min(c for r, c in exemplar)
    shape = frozenset((r-r0, c-c0) for r, c in exemplar)
    maxr = max(r for r, c in shape)
    maxc = max(c for r, c in shape)

    for color, seeds in parts.items():
        if color == exemplar_color:
            continue
        candidates = []
        for dr in range(h - maxr):
            for dc in range(w - maxc):
                placed = _translate(shape, dr, dc)
                covered = placed & seeds
                # Partial fragments can represent one or more translated motif copies.
                if len(covered) >= 2:
                    candidates.append((placed, covered))
        solutions = []
        def cover(covered, copies):
            if seeds <= covered:
                solutions.append(tuple(copies))
                return
            if len(copies) >= len(seeds):
                return
            point = min(seeds - covered,
                        key=lambda p: sum(p in c for _, c in candidates))
            for placed, overlap in candidates:
                if point in overlap and not (overlap & covered):
                    cover(covered | overlap, copies + [placed])
        cover(frozenset(), [])
        unions = {frozenset().union(*solution) for solution in solutions}
        if len(unions) == 1:
            for r, c in next(iter(unions)):
                out[r][c] = color
    return out


